changeSet.sql:

if not exists (select 1 from [sys].[key_constraints] where name = 'PK_AssetVersionRollupPath')
begin
	ALTER TABLE [metrics].[AssetVersionRollupPath] ADD CONSTRAINT [PK_AssetVersionRollupPath] PRIMARY KEY CLUSTERED ( [Uid] ASC )
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAssetVersionRollupPath_MetricAssetVersion')
begin
	ALTER TABLE [metrics].[AssetVersionRollupPath]  WITH CHECK ADD  CONSTRAINT [FK_MetricAssetVersionRollupPath_MetricAssetVersion] FOREIGN KEY([AssetVersionUid]) REFERENCES [metrics].[AssetVersion] ([Uid]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[AssetVersionRollupPath] CHECK CONSTRAINT [FK_MetricAssetVersionRollupPath_MetricAssetVersion];
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAssetVersionRollupPath_MetricRollupPath')
begin
	ALTER TABLE [metrics].[AssetVersionRollupPath]  WITH CHECK ADD  CONSTRAINT [FK_MetricAssetVersionRollupPath_MetricRollupPath] FOREIGN KEY([RollupPathUid]) REFERENCES [metrics].[RollupPath] ([Uid]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[AssetVersionRollupPath] CHECK CONSTRAINT [FK_MetricAssetVersionRollupPath_MetricRollupPath];
end
